6	import type { DragData, NoteEntry } from "@typenotes/shared/types";
7	import type { NotePreview } from "@typenotes/shared/format";
8	
9	export type NavNoteRowProps = {
10	  note: NoteEntry;
11	  preview?: NotePreview;
12	  parentPath: string;
13	  depth: number;
14	  indentationWidth: number;
15	  isSelected: boolean;
16	  draggable?: boolean;
17	  showGuides?: boolean;
18	  onSelect: (notePath: string, event: ReactMouseEvent, parentPath: string) => void;
19	  onContextMenu: (
20	    event: ReactMouseEvent,
21	    notePath: string,
22	    parentPath: string
23	  ) => void;
24	};
25	
26	export function NavNoteRow({
27	  note,
28	  preview,
29	  parentPath,
30	  depth,
31	  indentationWidth,
32	  isSelected,
33	  draggable = true,
34	  showGuides = false,
35	  onSelect,
36	  onContextMenu,
37	}: NavNoteRowProps) {
38	  const { attributes, listeners, setNodeRef, transform, isDragging } = useDraggable({
39	    id: note.path,
40	    data: { type: "note", path: note.path } satisfies DragData,
41	    disabled: !draggable,
42	  });
43	  const { setNodeRef: setDropRef, isOver } = useDroppable({
44	    id: note.path,
45	    data: { type: "note", path: note.path } satisfies DragData,
46	    disabled: !draggable,
47	  });
48	  const setRefs = useCallback(
49	    (element: HTMLDivElement | null) => {
50	      setNodeRef(element);
51	      setDropRef(element);
52	    },
53	    [setDropRef, setNodeRef]
54	  );
55	  const style = {
56	    transform: isDragging ? undefined : CSS.Translate.toString(transform),
57	    paddingLeft: 12 + depth * indentationWidth,
58	  } as React.CSSProperties;
59	  const guideBaseLeft = 12 + indentationWidth / 2;
60	  const title = preview?.title || "";
61	
62	  return (
63	    <div
64	      ref={setRefs}
65	      style={style}
66	      className={`item-row nav-note-row${isSelected ? " selected" : ""}${
67	        isOver ? " drop-inside" : ""
68	      }${isDragging ? " is-dragging" : ""}`}
69	      data-note={note.path}
70	      onClick={(event) => onSelect(note.path, event, parentPath)}
71	      onContextMenu={(event) => onContextMenu(event, note.path, parentPath)}
72	      {...listeners}
73	      {...attributes}
74	    >
75	      {showGuides && depth > 0 ? (
76	        <span className="tree-guides" aria-hidden>
77	          {Array.from({ length: depth }, (_, index) => (
78	            <span
79	              key={`depth-${index}`}
80	              className="tree-guide-vert"
81	              style={{ left: guideBaseLeft + index * indentationWidth }}
82	            />
83	          ))}
84	        </span>
85	      ) : null}
86	      <span className="icon-spacer" aria-hidden />
87	      <span className="nav-note-glyph" aria-hidden>
88	        <svg viewBox="0 0 24 24">
89	          <path
90	            d="M7 3.8h7l3.2 3.2V19a1.2 1.2 0 0 1-1.2 1.2H7A1.2 1.2 0 0 1 5.8 19V5A1.2 1.2 0 0 1 7 3.8z"
91	            fill="none"
92	            stroke="currentColor"
93	            strokeWidth="1.5"
94	            strokeLinejoin="round"
95	          />
96	          <path
97	            d="M13.9 3.8V7h3.3"
98	            fill="none"
99	            stroke="currentColor"
100	            strokeWidth="1.5"
101	            strokeLinecap="round"
102	            strokeLinejoin="round"
103	          />
104	        </svg>
105	      </span>
106	      <span className="item-label">{title}</span>
107	      {preview?.isArchived ? (
108	        <span className="nav-note-marker nav-note-marker-archived">Archived</span>
109	      ) : null}
110	      {preview?.isReviewed ? (
111	        <span className="nav-note-marker nav-note-marker-reviewed">Reviewed</span>
112	      ) : null}
113	      {preview?.isRecording ? (
114	        <Mic size={11} className="nav-note-recording-icon" />
115	      ) : preview?.isHandwriting ? (
116	        <PenLine size={11} className="nav-note-recording-icon" />
117	      ) : null}
118	    </div>
119	  );
120	}
121

