        <span className="nav-note-marker nav-note-marker-reviewed">Reviewed</span>
      ) : null}
      {preview?.isRecording ? (
        <Mic size={11} className="nav-note-recording-icon" />
      ) : preview?.isHandwriting ? (
        <PenLine size={11} className="nav-note-recording-icon" />
      ) : null}
    </div>
  );
}

import type { MouseEvent as ReactMouseEvent } from "react";
import { useCallback } from "react";
import { useDraggable, useDroppable } from "@dnd-kit/core";
import { CSS } from "@dnd-kit/utilities";
import { Mic, PenLine } from "lucide-react";
import type { DragData, NoteEntry } from "@typenotes/shared/types";
import type { NotePreview } from "@typenotes/shared/format";

export type NavNoteRowProps = {
  note: NoteEntry;
  preview?: NotePreview;
  parentPath: string;
  depth: number;
  indentationWidth: number;
  isSelected: boolean;
  draggable?: boolean;
  onSelect: (notePath: string, event: ReactMouseEvent, parentPath: string) => void;
  onContextMenu: (
    event: ReactMouseEvent,
    notePath: string,
    parentPath: string
  ) => void;
};

export function NavNoteRow({
  note,
  preview,
  parentPath,
  depth,
  indentationWidth,
  isSelected,
  draggable = true,
  onSelect,
  onContextMenu,
}: NavNoteRowProps) {
  const { attributes, listeners, setNodeRef, transform, isDragging } = useDraggable({
    id: note.path,
    data: { type: "note", path: note.path } satisfies DragData,
    disabled: !draggable,
  });
  const { setNodeRef: setDropRef, isOver } = useDroppable({
    id: note.path,
    data: { type: "note", path: note.path } satisfies DragData,
    disabled: !draggable,
  });
  const setRefs = useCallback(
    (element: HTMLDivElement | null) => {
      setNodeRef(element);
      setDropRef(element);
    },
    [setDropRef, setNodeRef]
  );
  const style = {
    transform: isDragging ? undefined : CSS.Translate.toString(transform),
    paddingLeft: 12 + depth * indentationWidth,
  } as React.CSSProperties;
  const guideBaseLeft = 12 + indentationWidth / 2;
  const title = preview?.title || "";

  return (
    <div
      ref={setRefs}
      style={style}
      className={`item-row nav-note-row${isSelected ? " selected" : ""}${
        isOver ? " drop-inside" : ""
      }${isDragging ? " is-dragging" : ""}`}
      data-note={note.path}
      onClick={(event) => onSelect(note.path, event, parentPath)}
      onContextMenu={(event) => onContextMenu(event, note.path, parentPath)}
      {...listeners}
      {...attributes}
    >
      {showGuides && depth > 0 ? (
        <span className="tree-guides" aria-hidden>
          {Array.from({ length: depth }, (_, index) => (
            <span
              key={`depth-${index}`}
              className="tree-guide-vert"
              style={{ left: guideBaseLeft + index * indentationWidth }}
            />
          ))}
        </span>
      ) : null}
      <span className="icon-spacer" aria-hidden />
      <span className="nav-note-glyph" aria-hidden>
        <svg viewBox="0 0 24 24">
          <path
            d="M7 3.8h7l3.2 3.2V19a1.2 1.2 0 0 1-1.2 1.2H7A1.2 1.2 0 0 1 5.8 19V5A1.2 1.2 0 0 1 7 3.8z"
            fill="none"
            stroke="currentColor"
            strokeWidth="1.5"
            strokeLinejoin="round"
          />
          <path
            d="M13.9 3.8V7h3.3"
            fill="none"
            stroke="currentColor"
            strokeWidth="1.5"
            strokeLinecap="round"
            strokeLinejoin="round"
          />
        </svg>
      </span>
      <span className="item-label">{title}</span>
      {preview?.isArchived ? (
        <span className="nav-note-marker nav-note-marker-archived">Archived</span>
      ) : null}
      {preview?.isReviewed ? (
        <span className="nav-note-marker nav-note-marker-reviewed">Reviewed</span>
      ) : null}
      {preview?.isRecording ? (
        <Mic size={11} className="nav-note-recording-icon" />
      ) : preview?.isHandwriting ? (
        <PenLine size={11} className="nav-note-recording-icon" />
      ) : null}
    </div>
  );
}

