      path: "Feed",
      children: [],
      notes: [
        { name: "n1.md", path: "Feed/2024-note-one.md" },
        { name: "n2.md", path: "Feed/2024-note-two.md" }
      ]
    },
    { name: "Archieve", path: "Archieve", children: [], notes: [] },
    {
      name: "Personal",
      path: "Personal",
      children: [
        {
          name: "Journal",
          path: "Personal/Journal",
          children: [],
          notes: [
            { name: "j1.md", path: "Personal/Journal/entry-one-with-a-longer-title.md" },
            { name: "j2.md", path: "Personal/Journal/entry-two.md" }
          ]
        }
      ],
      notes: [
        { name: "todo.md", path: "Personal/todo.md" }
      ]
    },
    {
      name: "Work Projects",
