  (node.children || []).forEach((c) => allPaths(c, acc));
  return acc;
}
const previewsByPath = {};
allPaths(folderTree).forEach((p, i) => {
  const title = p.split("/").pop().replace(/\\.md$/, "").replace(/-/g, " ");
  previewsByPath[p] = {
