    meta: {
      created_ms: NOW - i * 3600000,
      updated_ms: NOW - i * 1800000
    }
  };
});
window.__TAURI_INTERNALS__.invoke = async function(cmd, args) {
  switch (cmd) {
    case "get_security_state":
      return { encryption_enabled: false, locked: false, auto_lock_on_background: false };
