      return {
        active_profile_id: "demo",
        profiles: [{
          id: "demo",
          name: "Demo",
          description: "",
          notes_root: "/demo/notes",
          settings: {
            git_remote_url: "", git_branch: "", git_username: "", git_password: "",
            git_commit_message: "", mobile_auto_transcription_enabled: false,
