          note_file_name_format: "utc_timestamp_slug"
        }
      };
    case "get_tree":
      return folderTree;
    case "list_note_previews": {
      const paths = (args && args.paths) || [];
      return paths.map((p) => previewsByPath[p] || { path: p, content: "", meta: { created_ms: NOW, updated_ms: NOW } });
    }
    case "set_order":
    case "move_items":
    case "rename_item":
      return null;
    default:
      return null;
  }
};
`;

const browser = await chromium.launch({ args: ["--no-sandbox"] });
const page = await browser.newPage({ viewport: { width: 1280, height: 860 } });
page.on("pageerror", (err) => console.log("[pageerror]", err.message));
await page.addInitScript(mockScript);
await page.goto(url, { waitUntil: "networkidle", timeout: 30000 });

await page.waitForSelector("text=Personal", { timeout: 15000 });
await page.waitForTimeout(500);

// Folders tab should be default when there's no Feed-only content; click it explicitly.
