// Expand "Work Projects" folder if collapsed, hover a note row.
const workRow = page.locator(".folder-row", { hasText: "Work Projects" }).first();
if (await workRow.count()) {
  await workRow.hover();
  await page.waitForTimeout(150);
  await page.screenshot({ path: `${outDir}/folders-hover.png` });
}

// Switch to Feed tab.
const feedTab = page.locator(".folders-tab-trigger", { hasText: "Feed" });
if (await feedTab.count()) {
  await feedTab.click();
  await page.waitForTimeout(400);
}
await page.screenshot({ path: `${outDir}/feed-tab.png` });

const feedRow = page.locator(".item-row").first();
if (await feedRow.count()) {
  await feedRow.hover();
  await page.waitForTimeout(150);
  await page.screenshot({ path: `${outDir}/feed-hover.png` });
}

console.log("done");
